results.sql:
SELECT
  (
    (
      SUM(CASE WHEN strftime('%Y', Date) = '2010' THEN 1 ELSE 0 END) -
      SUM(CASE WHEN strftime('%Y', Date) = '2011' THEN 1 ELSE 0 END)
    ) * 100.0 / COUNT(*)
  )
FROM badges
WHERE
  Name = 'Student';

